import re,subprocess
base='b430f9f42'; land='7daf51fe8'
paths=subprocess.run(['git','diff','--name-only',base,land,'--','ProjectFortress','Library','Specification'],capture_output=True,text=True).stdout.split()
paths=[p for p in paths if not re.match(r'ProjectFortress/(tests|compiler_tests|library_tests)/',p) and not p.endswith('.pdf')]
bybase={}
for p in paths: bybase.setdefault(p.split('/')[-1],[]).append(p)
def mapping(p):
    out=subprocess.run(['git','diff','-U0',base,land,'--',p],capture_output=True,text=True).stdout
    hunks=[]
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@',out,re.M):
        a=int(m.group(1)); b=int(m.group(2) or 1); c=int(m.group(3)); d=int(m.group(4) or 1)
        hunks.append((a,b,c,d))
    return hunks
cache={}
def newline(p,n):
    if p not in cache: cache[p]=mapping(p)
    off=0
    for a,b,c,d in cache[p]:
        start=a if b>0 else a+1
        if b==0:
            if n>a: off+= d
            continue
        if n<a: break
        if a<=n<a+b: return None  # changed line
        off+= d-b
    return n+off
changed=set('F-32 F-53 F-55 F-57 F-73 F-74 F-79 F-84 F-118 F-123 F-131 F-137 F-138 F-140 F-151 F-228 F-229 F-240 F-249 F-253 F-262 F-263 F-278 F-285 F-299 F-304 F-326 F-328 F-331 F-339 F-340 F-341 F-342 F-343 F-344 F-345 F-346'.split())
for fn in ['explorations/coordinator/FACTS.md','explorations/coordinator/POSITIONS.md']:
    for line in open(fn):
        m=re.match(r'- ([FP]-\d+) ',line)
        if not m or m.group(1) in changed: continue
        res=[]
        for mm in re.finditer(r'`([A-Za-z0-9_./-]+\.(?:java|scala|fss|fsi|tex))`?:(\d+)',line):
            path,n=mm.group(1),int(mm.group(2))
            if 'Specification-1.0-frozen' in path: continue
            pre=line[max(0,mm.start()-15):mm.start()]
            if re.search(r'[0-9a-f]{7,}:$',pre): continue
            tail=line[mm.end():mm.end()+40]
            if re.match(r'[-\d,`: and]*\s*(at|in the parent of)\s+`?[0-9a-f]{7,}',tail): continue
            cands=[p for p in bybase.get(path.split('/')[-1],[]) if p.endswith(path) or path.endswith(p.split('/')[-1])]
            cands=[p for p in cands if p.endswith(path)] or cands
            if not cands: continue
            if len(cands)>1:
                cands=[c for c in cands if c.endswith(path)]
                if len(cands)!=1: res.append(f'{path}:{n} ambiguous'); continue
            nn=newline(cands[0],n)
            if nn!=n: res.append(f'{path}:{n}->{nn}')
        if res: print(m.group(1),'; '.join(res))
EOF

